package de.lazytv.pro.catalog;
import org.json.*;import java.util.*;import de.lazytv.pro.playlist.Playlist;
public class XtreamCatalogSource {public Catalog load(Playlist p)throws CatalogException{String base=base(p),q=auth(p);JSONObject login=obj(HttpClient.get(base+"/player_api.php?"+q,null));JSONObject ui=login.optJSONObject("user_info");if(ui==null||!"1".equals(ui.optString("auth")))throw new CatalogException("Xtream credentials janë të gabuara ose llogaria nuk është aktive");Catalog c=new Catalog();loadType(c,base,p,"get_live_categories","get_live_streams",CatalogType.LIVE);loadType(c,base,p,"get_vod_categories","get_vod_streams",CatalogType.MOVIES);loadType(c,base,p,"get_series_categories","get_series",CatalogType.SERIES);if(c.isEmpty())throw new CatalogException("Xtream u lidh, por katalogu është bosh");return c;}public SeriesDetails loadSeries(Playlist p,String seriesId)throws CatalogException{JSONObject root=obj(HttpClient.get(base(p)+"/player_api.php?"+auth(p)+"&action=get_series_info&series_id="+HttpClient.enc(seriesId),null));SeriesDetails d=new SeriesDetails();JSONObject info=root.optJSONObject("info");String defaultCover=info==null?"":info.optString("cover");JSONArray ss=root.optJSONArray("seasons");if(ss!=null)for(int i=0;i<ss.length();i++){JSONObject s=ss.optJSONObject(i);if(s==null)continue;int n=s.optInt("season_number",s.optInt("season",i+1));d.seasons.add(new Season(String.valueOf(n),s.optString("name","Season "+n),seriesId,n,s.optString("cover",defaultCover)));}JSONObject eps=root.optJSONObject("episodes");if(eps!=null){Iterator<String> it=eps.keys();while(it.hasNext()){String key=it.next();JSONArray a=eps.optJSONArray(key);if(a==null)continue;int sn=intval(key,0);List<Episode> list=d.episodes.computeIfAbsent(sn,k->new ArrayList<>());for(int i=0;i<a.length();i++){JSONObject e=a.optJSONObject(i);if(e==null)continue;String id=e.optString("id",e.optString("stream_id"));JSONObject ei=e.optJSONObject("info");String ext=e.optString("container_extension",ei==null?"mp4":ei.optString("container_extension","mp4"));int en=e.optInt("episode_num",i+1);int season=e.optInt("season",sn);String title=e.optString("title",e.optString("name","Episode "+en));String image=ei==null?defaultCover:ei.optString("movie_image",ei.optString("cover_big",defaultCover));String duration=ei==null?"":ei.optString("duration");Map<String,String> meta=new LinkedHashMap<>();if(ei!=null){put(meta,"plot",ei.optString("plot"));put(meta,"rating",ei.optString("rating"));put(meta,"releasedate",ei.optString("releasedate"));}String url=base(p)+"/series/"+p.getUsername()+"/"+p.getPassword()+"/"+id+"."+ext;list.add(new Episode(id,title,seriesId,"",image,url,ext,duration,season,en,meta));}}}if(d.seasons.isEmpty())for(Integer n:d.episodes.keySet())d.seasons.add(new Season(String.valueOf(n),"Season "+n,seriesId,n,defaultCover));if(d.isEmpty())throw new CatalogException("Seriali nuk ka sezone ose episode");return d;}private void loadType(Catalog c,String b,Playlist p,String ca,String ia,CatalogType t)throws CatalogException{String q="&"+auth(p);JSONArray cats=arr(HttpClient.get(b+"/player_api.php?action="+ca+q,null));LinkedHashMap<String,String> known=new LinkedHashMap<>();for(int i=0;i<cats.length();i++){JSONObject o=cats.optJSONObject(i);if(o!=null){String cid=o.optString("category_id").trim();String cn=o.optString("category_name","Të tjera").trim();if(!cid.isEmpty()){known.put(cid,cn);c.categories.add(new Category(cid,cn,t));}}}JSONArray a=arr(HttpClient.get(b+"/player_api.php?action="+ia+q,null));LinkedHashMap<String,Integer> missing=new LinkedHashMap<>();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String id=t==CatalogType.SERIES?o.optString("series_id"):o.optString("stream_id");String ext=o.optString("container_extension",t==CatalogType.LIVE?"ts":"mp4");String url=t==CatalogType.LIVE?b+"/live/"+p.getUsername()+"/"+p.getPassword()+"/"+id+"."+ext:t==CatalogType.MOVIES?b+"/movie/"+p.getUsername()+"/"+p.getPassword()+"/"+id+"."+ext:"";String cid=o.optString("category_id").trim();if(cid.isEmpty())cid="uncategorized";if(!known.containsKey(cid))missing.put(cid,missing.containsKey(cid)?missing.get(cid)+1:1);c.items.add(CatalogItems.create(id,o.optString("name","Stream"),cid,o.optString("stream_icon",o.optString("cover")),url,o.optString("epg_channel_id"),t));}for(Map.Entry<String,Integer>e:missing.entrySet()){String cid=e.getKey();String label="Kategori "+cid;if("uncategorized".equals(cid))label="Të pakategorizuara";c.categories.add(new Category(cid,label,t));} }private String base(Playlist p){return p.getUrl().replaceAll("/+$","");}private String auth(Playlist p){return "username="+HttpClient.enc(p.getUsername())+"&password="+HttpClient.enc(p.getPassword());}private JSONObject obj(String s)throws CatalogException{try{return new JSONObject(s);}catch(Exception e){throw new CatalogException("Përgjigje Xtream e pavlefshme",e);}}private JSONArray arr(String s)throws CatalogException{try{return new JSONArray(s);}catch(Exception e){throw new CatalogException("Përgjigje Xtream e pavlefshme",e);}}private int intval(String s,int d){try{return Integer.parseInt(s);}catch(Exception e){return d;}}private static void put(Map<String,String>m,String k,String v){if(v!=null&&!v.isEmpty())m.put(k,v);}}
